import type { MilitaryService } from '~/client';

export const militaryServiceConfig: Record<MilitaryService, { label: string }> = {
  military_family: { label: 'Military Family' },
  military_spouse: { label: 'Military Spouse' },
  veteran: { label: 'Veteran' },
  na: { label: 'N/A' },
};

export const militaryServiceValues = Object.keys(militaryServiceConfig) as [MilitaryService, ...MilitaryService[]];

export const militaryServiceOptions: SelectItem<MilitaryService>[] = Object.entries(militaryServiceConfig).map(
  ([value, { label }]) => ({ value: value as MilitaryService, name: label })
);
